argv:
$ErrorActionPreference='Stop'
$root='E:\WebAIBridge-R68-OBSERVABILITY-20261014-GPT6'
$expected='1173e893a0b4ded2f92e27b72e99f36f1a96f2ab'
if(([string](& git.exe -C $root rev-parse HEAD)).Trim() -ne $expected){throw 'SOURCE_MOVED'}
if(([string](& git.exe -C 'E:\WebAIBridge' rev-parse HEAD)).Trim() -ne '66e2ca7681b5e4c4affde9641b69e5582b718f99'){throw 'PRODUCTION_CHANGED'}
if(Get-NetTCPConnection -LocalPort 17450 -State Listen -ErrorAction SilentlyContinue){throw 'PORT_NOW_TAKEN'}
$node=(Get-Command node.exe -ErrorAction Stop).Source
$script=Join-Path $root 'app\r68-live-viewer.js'
$out=Join-Path $root 'R68_VIEWER_17450_STDOUT.log'
$err=Join-Path $root 'R68_VIEWER_17450_STDERR.log'
if((Test-Path $out) -or (Test-Path $err)){throw 'OBSERVER_LOG_ALREADY_EXISTS'}
$env:R68_OBSERVER_DATA_DIR='E:\WebAIBridge\app\data'
$env:R68_OBSERVER_PORT='17450'
$proc=Start-Process -FilePath $node -ArgumentList @($script) -WorkingDirectory (Join-Path $root 'app') -WindowStyle Hidden -RedirectStandardOutput $out -RedirectStandardError $err -PassThru
Write-Output ('OBSERVER_PID='+$proc.Id)
$ready=$false
for($i=0;$i -lt 10;$i++){
 Start-Sleep -Milliseconds 650
 try {
  $d=Invoke-RestMethod -Uri 'http://127.0.0.1:17450/api/live' -Method Get -TimeoutSec 3
  if($d.contract -eq 'bridge.r68.live_chat_observability.v1' -and $d.readOnly -eq $true -and $d.guardrails.noSend -eq $true){
   Write-Output 'VIEWER_READY=True'
   Write-Output ('CHATS_OPEN='+$d.openCount)
   Write-Output ('CHATS_NOT_REGISTERED='+$d.unregisteredOpenCount)
   Write-Output ('ASSIGNMENTS='+@($d.assignments).Count)
   Write-Output ('SOURCE_COMPLETE='+$d.scanComplete)
   $ready=$true
   break
  }
 }catch{}
}
if(-not $ready){throw 'START_EFFECT_UNKNOWN_RECONCILE_PID'}
Write-Output ('PRODUCTION_HEAD='+(& git.exe -C 'E:\WebAIBridge' rev-parse HEAD))
Write-Output ('BRIDGE_17448_LISTEN='+[bool](Get-NetTCPConnection -LocalPort 17448 -State Listen -ErrorAction SilentlyContinue))
Write-Output 'LIVE_URL=http://127.0.0.1:17450/'
